begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select plan(10);
select ok(not has_table_privilege('authenticated','notification_private.zalo_credentials','SELECT'),'authenticated cannot read tokens');
select ok(not has_table_privilege('service_role','notification_private.zalo_credentials','SELECT'),'service direct table reads denied');
select ok(not has_function_privilege('anon','public.zalo_credential_command(text,text,text,bigint,uuid,text,text,timestamptz,text)','EXECUTE'),'anonymous cannot access credential RPC');
select ok(not has_function_privilege('authenticated','notification_private.zalo_decrypt(text)','EXECUTE'),'authenticated cannot decrypt');
select ok(not has_function_privilege('authenticated','public.zalo_oauth_state(text,text,uuid,text,text,text,bigint)','EXECUTE'),'authenticated cannot bypass OAuth controller');
insert into auth.users(id) values('ab280000-0000-4000-8000-000000000001');
insert into profiles(id,full_name,status) values('ab280000-0000-4000-8000-000000000001','TEST OAuth Admin','ACTIVE');
insert into user_roles(user_id,role_id) select 'ab280000-0000-4000-8000-000000000001',id from roles where code='SUPER_ADMIN';
select is(public.zalo_oauth_state('CREATE',repeat('a',64),'ab280000-0000-4000-8000-000000000001','123456789','987654321',repeat('v',43),1)->>'state','CREATED','state created for admin');
select throws_ok($$select public.zalo_oauth_state('CONSUME',repeat('a',64),'ab280000-0000-4000-8000-000000000001','123456789','111111111')$$,'P0001','OAUTH_INVALID','wrong OA denied');
select is(public.zalo_oauth_state('CONSUME',repeat('a',64),'ab280000-0000-4000-8000-000000000001','123456789','987654321')->>'verifier',repeat('v',43),'correct admin consumes state');
select throws_ok($$select public.zalo_oauth_state('CONSUME',repeat('a',64),'ab280000-0000-4000-8000-000000000001','123456789','987654321')$$,'P0001','OAUTH_INVALID','replay denied');
select public.zalo_oauth_state('CREATE',repeat('b',64),'ab280000-0000-4000-8000-000000000001','123456789','987654321',repeat('v',43),1);
update notification_private.zalo_oauth_states set expires_at=clock_timestamp()-interval '1 second' where state_hash=repeat('b',64);
select throws_ok($$select public.zalo_oauth_state('CONSUME',repeat('b',64),'ab280000-0000-4000-8000-000000000001','123456789','987654321')$$,'P0001','OAUTH_INVALID','expired state denied');
select * from finish();
rollback;
